INSERT INTO scheduled_tasks VALUES('task-e6e7dcad9a',0,NULL,'{"title": "Pre-open market brief \u2014 Sigma system", "instructions": "Brief me on my Sigma trading system before the market opens.\n\nHOW TO READ THE DATA \u2014 read this before starting:\nThree small files are staged in your own workspace a few minutes before each run. Read them with your file tools, by plain filename:\n- status_report.json \u2014 live account state.\n- decisions-summary.json \u2014 which decisions file was staged, the trading day, row counts by decision, and the list of GO tickers.\n- decisions-go.csv \u2014 one row per GO decision, with scores and reasons.\n\nDo NOT use run_shell, ls, cat, curl or a Python script, and do not try to reach into ~/quantumGlobalGroup/ \u2014 you run unattended and cannot see outside this workspace, so any shell command stops the run to wait for a human and the brief never gets written. Everything you need is already staged here. Web search IS allowed and needs no approval.\n\nWORK, DON''T NARRATE: do not end your turn to describe what you are about to do. Carry each step through. The run is not finished until market-brief-YYYY-MM-DD.md exists in this workspace \u2014 write it as your final action, every time, even if some step failed. A brief that says \"news lookup failed for X\" is a success; no file at all is a failure.\n\nWHAT TO PRODUCE:\n\nstatus_report.json holds three accounts \u2014 A = Mean-Reversion, B = Momentum, C = Options/High-Vol \u2014 each with equity, cash, position count and unrealized P&L, plus portfolio_value, daily_pnl, circuit_breaker_tripped, and a `swallowed` map of suppressed API errors.\n\n1. Account state \u2014 equity and daily P&L per account, portfolio total, and what changed since the previous brief if an earlier market-brief file exists in this workspace.\n2. Active names \u2014 take go_tickers from decisions-summary.json. For each, search news since the last close and flag anything that would invalidate the thesis: earnings, guidance changes, sector shocks, M&A, regulatory action. Use decisions-go.csv for the scores and stated reason behind each. If there are more than 10 GO tickers, cover the 10 with the highest total_score and say how many you skipped.\n3. Operational health \u2014 if decisions-summary.json''s trading_day is not the current or previous trading day, say so prominently: it means the trading daemon stopped producing decision logs. Also flag circuit_breaker_tripped being true, any large counts in `swallowed`, and any account present in status_report.json but missing from accounts_seen (that account evaluated nothing). These are system failures and matter more than market commentary.\n\nLead the file with anything needing a decision before the open. This is informational \u2014 do not place, modify, or recommend specific trades to execute.\n\nFOCUS \u2014 do this before anything else:\n  1. read_file FOCUS.md in your own workspace. It is rewritten every Monday from what I\n     actually worked on: the projects in play, the open questions, and what I have parked.\n  2. Tag every item you report ON-FOCUS or ADJACENT. ON-FOCUS bears on a project or open\n     question named in FOCUS.md; ADJACENT does not, but is worth knowing anyway.\n  3. Lead with ON-FOCUS. Keep the ADJACENT ones \u2014 being shown only what I already care about\n     is exactly how I get stuck \u2014 but cap them at three and put them last.\n  4. If FOCUS.md is missing, say so in one line and treat everything as ADJACENT.\n", "schedule": {"kind": "cron", "cron": "30 7 * * 1-5", "fire_at": null, "timezone": "local"}, "workspace": "/home/iconbaypark2900/OpenWorker/__task__task-e6e7dcad9a", "origin_surface": "cowork", "origin_session_id": "", "agent": "research", "id": "task-e6e7dcad9a", "task_session_id": "__task__task-e6e7dcad9a", "model": "openai:ornith-nothink", "notify_on_completion": true, "notify_target": null, "always_allowed_tools": ["brain_note", "brain_recall", "grep", "list_files", "read_file", "read_file_lines", "remember", "todo_write", "web_fetch", "web_search", "write_file"], "always_allowed_commands": [], "enabled": false, "created_at": 1786900127.0080872, "updated_at": 1787415570.860385, "next_run": null, "last_run": 1786905365.4827797, "last_status": "ok", "run_count": 3, "max_runs": null, "seen_runs_at": 1787250195.8118854}');
INSERT INTO scheduled_tasks VALUES('task-d6306af97d',1,1788260400.0,'{"title": "Monthly report \u2014 themes and drift", "instructions": "Summarise the month from the weekly reviews \u2014 NOT from the daily briefs. Each level of\nthis ladder reads only the level below it; that is what keeps it affordable and what makes the\nsummaries progressively more strategic instead of progressively longer.\n\nREAD: every file in /home/iconbaypark2900/OpenWorker/knowledge/reports/weekly/ from the month just ended (4-5 files), plus\n/home/iconbaypark2900/OpenWorker/knowledge/FOCUS.md and last month''s report in /home/iconbaypark2900/OpenWorker/knowledge/reports/monthly/.\n\nWRITE /home/iconbaypark2900/OpenWorker/knowledge/reports/monthly/<YYYY>-<MM>.md:\n\n  ## What shipped\n  Things that reached a finished state this month. Be strict \u2014 \"worked on\" is not \"shipped\".\n\n  ## Themes\n  What the weeks had in common that no single week showed. A problem that recurred in three\n  different projects is a theme; something that happened once is not.\n\n  ## Drift\n  Where the month''s actual work diverged from what FOCUS.md said the focus was. State it\n  neutrally \u2014 drift is sometimes the right call and sometimes the reason nothing shipped.\n\n  ## Stop doing\n  At most three. Things consuming attention with nothing to show: a project with commits but no\n  outcome, a report I never act on, an automation whose output never appears in a decision.\n  Include automations on this schedule \u2014 an unread report is a cost.\n\n  ## Still unexamined\n  Items that appeared in the Unexamined section of two or more weekly reviews. These have now\n  survived a month of being ignored; say what that means.\n\nBUDGET: at most 20 tool calls.\n\nRULES:\n  - Read only the weeklies. If a week''s review is missing, say which and carry on.\n  - No new research. This is a report about my reports.\n\nSHELL RULES \u2014 you are unattended, so keep every command small and reviewable:\n  - NEVER inline a multi-line script (no heredocs). Write it to a file with write_file, then\n    run that file.\n  - One command does one thing. Cap output: head, tail -n, wc -l, --quiet.\n  - Use native paths (/home/iconbaypark2900/...). The filesystem MCP server sees this machine''s\n    home as /data/home instead, so its paths and shell paths are NOT interchangeable \u2014 prefer\n    shell for files, and only use qdrant through MCP.\n  - /home/iconbaypark2900/OpenWorker/knowledge is a WRITABLE ROOT of this session. Use the normal file\n    tools on it with absolute paths \u2014 read_file, write_file, list_files all work there, and\n    they are more reliable than shell redirection. Shell is for git, sqlite, find and curl.\n\nCONTINUITY \u2014 do this FIRST, before any searching:\n  1. list_files in your workspace and read the 1-2 most recent prior outputs of this\n     same job (they share this file-naming pattern).\n  2. Carry forward what is still live, mark what has closed or been resolved, and spend\n     your search budget on what is genuinely NEW since then.\n  3. If something you reported before has changed state, say so explicitly \u2014 \"X, first\n     flagged <date>, is now <state>\" is worth more than rediscovering X as if it were new.\n  4. Never re-report an unchanged item as a fresh finding.\nThis job runs on a schedule and its outputs accumulate; the value is in the running\nrecord, not in a fresh cold start every time.\n\nFOCUS \u2014 do this before anything else:\n  1. read_file FOCUS.md in your own workspace. It is rewritten every Monday from what I\n     actually worked on: the projects in play, the open questions, and what I have parked.\n  2. Tag every item you report ON-FOCUS or ADJACENT. ON-FOCUS bears on a project or open\n     question named in FOCUS.md; ADJACENT does not, but is worth knowing anyway.\n  3. Lead with ON-FOCUS. Keep the ADJACENT ones \u2014 being shown only what I already care about\n     is exactly how I get stuck \u2014 but cap them at three and put them last.\n  4. If FOCUS.md is missing, say so in one line and treat everything as ADJACENT.\n\nTHREADS \u2014 keep the durable record current, not just the dated one:\n  Your dated report is the evidence; the brain''s threads are the memory a future session reads.\n  After writing the report, for each subject that MOVED this run:\n    1. `brain_recall` the subject to find its existing thread \u2014 extend that thread, never fork a\n       near-duplicate of it.\n    2. `brain_note` one entry: what changed, with the specifics, and `source` set to the file you\n       just wrote.\n    3. Pass `now` ONLY if the subject''s current state actually changed. That line is what keeps a\n       stale claim from being retrieved later as if it were still true.\n  A quiet run notes nothing. Inventing movement to have something to record is worse than silence.\n", "schedule": {"kind": "cron", "cron": "0 7 1 * *", "fire_at": null, "timezone": "local"}, "workspace": "/home/iconbaypark2900/openworker-tasks/__task__task-d6306af97d", "origin_surface": "cowork", "origin_session_id": "", "agent": "repo-ops", "id": "task-d6306af97d", "task_session_id": "__task__task-d6306af97d", "model": null, "notify_on_completion": true, "notify_target": null, "always_allowed_tools": ["brain_note", "brain_recall", "grep", "list_files", "mcp__qdrant__qdrant-qdrant-find", "mcp__qdrant__qdrant-qdrant-store", "read_file", "read_file_lines", "remember", "run_shell", "todo_write", "write_file"], "always_allowed_commands": [], "enabled": true, "created_at": 1787415295.916137, "updated_at": 1787488295.086646, "next_run": 1788260400.0, "last_run": null, "last_status": null, "run_count": 0, "max_runs": null, "seen_runs_at": 0.0}');
INSERT INTO scheduled_tasks VALUES('task-3c31fb8c75',1,1790854200.0,'{"title": "Quarterly review \u2014 strategy and focus revision", "instructions": "Review the quarter from the three monthly reports, and propose how the focus should\nchange. This is the level where the question stops being \"what happened\" and becomes \"is this\nstill the right thing to be doing\".\n\nREAD: the three monthly reports for the quarter in /home/iconbaypark2900/OpenWorker/knowledge/reports/monthly/, the current\n/home/iconbaypark2900/OpenWorker/knowledge/FOCUS.md, and the previous quarterly in /home/iconbaypark2900/OpenWorker/knowledge/reports/quarterly/.\n\nWRITE /home/iconbaypark2900/OpenWorker/knowledge/reports/quarterly/<YYYY>-Q<n>.md:\n\n  ## The quarter in five lines\n  What actually happened. Five lines, no more.\n\n  ## What compounded\n  Work where this quarter built on the last one. This is the only kind of progress that\n  survives; name it precisely and say what made it possible.\n\n  ## What was churn\n  Effort that left nothing behind \u2014 restarts, abandoned directions, the same problem solved\n  twice. Say what it cost in weeks.\n\n  ## Proposed FOCUS.md revision\n  A concrete diff, NOT applied: which Active entries to drop, which Went-quiet entries to\n  formally park, which open questions are answered, and at most one thing to add. Give the\n  reason for each line. I decide whether to take it \u2014 never edit FOCUS.md from this job.\n\n  ## The bet\n  If the next quarter can only advance one of the Active projects, which one and why. Argue\n  for it; a ranked list with no argument is a dodge.\n\nBUDGET: at most 20 tool calls. No new research \u2014 this reads my own reports.\n\nRULES:\n  - Judge from the record, not from what would be encouraging to read.\n  - Three monthlies is the whole input. If one is missing, say so and weight accordingly.\n\nSHELL RULES \u2014 you are unattended, so keep every command small and reviewable:\n  - NEVER inline a multi-line script (no heredocs). Write it to a file with write_file, then\n    run that file.\n  - One command does one thing. Cap output: head, tail -n, wc -l, --quiet.\n  - Use native paths (/home/iconbaypark2900/...). The filesystem MCP server sees this machine''s\n    home as /data/home instead, so its paths and shell paths are NOT interchangeable \u2014 prefer\n    shell for files, and only use qdrant through MCP.\n  - /home/iconbaypark2900/OpenWorker/knowledge is a WRITABLE ROOT of this session. Use the normal file\n    tools on it with absolute paths \u2014 read_file, write_file, list_files all work there, and\n    they are more reliable than shell redirection. Shell is for git, sqlite, find and curl.\n\nCONTINUITY \u2014 do this FIRST, before any searching:\n  1. list_files in your workspace and read the 1-2 most recent prior outputs of this\n     same job (they share this file-naming pattern).\n  2. Carry forward what is still live, mark what has closed or been resolved, and spend\n     your search budget on what is genuinely NEW since then.\n  3. If something you reported before has changed state, say so explicitly \u2014 \"X, first\n     flagged <date>, is now <state>\" is worth more than rediscovering X as if it were new.\n  4. Never re-report an unchanged item as a fresh finding.\nThis job runs on a schedule and its outputs accumulate; the value is in the running\nrecord, not in a fresh cold start every time.\n\nFOCUS \u2014 do this before anything else:\n  1. read_file FOCUS.md in your own workspace. It is rewritten every Monday from what I\n     actually worked on: the projects in play, the open questions, and what I have parked.\n  2. Tag every item you report ON-FOCUS or ADJACENT. ON-FOCUS bears on a project or open\n     question named in FOCUS.md; ADJACENT does not, but is worth knowing anyway.\n  3. Lead with ON-FOCUS. Keep the ADJACENT ones \u2014 being shown only what I already care about\n     is exactly how I get stuck \u2014 but cap them at three and put them last.\n  4. If FOCUS.md is missing, say so in one line and treat everything as ADJACENT.\n\nTHREADS \u2014 keep the durable record current, not just the dated one:\n  Your dated report is the evidence; the brain''s threads are the memory a future session reads.\n  After writing the report, for each subject that MOVED this run:\n    1. `brain_recall` the subject to find its existing thread \u2014 extend that thread, never fork a\n       near-duplicate of it.\n    2. `brain_note` one entry: what changed, with the specifics, and `source` set to the file you\n       just wrote.\n    3. Pass `now` ONLY if the subject''s current state actually changed. That line is what keeps a\n       stale claim from being retrieved later as if it were still true.\n  A quiet run notes nothing. Inventing movement to have something to record is worse than silence.\n", "schedule": {"kind": "cron", "cron": "30 7 1 1,4,7,10 *", "fire_at": null, "timezone": "local"}, "workspace": "/home/iconbaypark2900/openworker-tasks/__task__task-3c31fb8c75", "origin_surface": "cowork", "origin_session_id": "", "agent": "repo-ops", "id": "task-3c31fb8c75", "task_session_id": "__task__task-3c31fb8c75", "model": null, "notify_on_completion": true, "notify_target": null, "always_allowed_tools": ["brain_note", "brain_recall", "grep", "list_files", "mcp__qdrant__qdrant-qdrant-find", "mcp__qdrant__qdrant-qdrant-store", "read_file", "read_file_lines", "remember", "run_shell", "todo_write", "write_file"], "always_allowed_commands": [], "enabled": true, "created_at": 1787415295.9170063, "updated_at": 1787488295.087891, "next_run": 1790854200.0, "last_run": null, "last_status": null, "run_count": 0, "max_runs": null, "seen_runs_at": 0.0}');
INSERT INTO scheduled_tasks VALUES('task-b5517950bb',1,1798804800.0,'{"title": "Yearly review \u2014 the year in the record", "instructions": "Write the year from the four quarterly reviews. One page. This is the document I read\nwhen deciding what the next year is for, so it has to be honest about the last one.\n\nREAD: the four quarterlies in /home/iconbaypark2900/OpenWorker/knowledge/reports/quarterly/, plus the current\n/home/iconbaypark2900/OpenWorker/knowledge/FOCUS.md.\n\nWRITE /home/iconbaypark2900/OpenWorker/knowledge/reports/yearly/<YYYY>.md, one page, these sections:\n\n  ## What exists now that did not a year ago\n  Concrete artifacts \u2014 shipped systems, published work, capabilities. If the list is short,\n  let it be short.\n\n  ## What I learned\n  Things that changed how I work, drawn from the record rather than sentiment.\n\n  ## What I kept doing that did not work\n  Patterns visible across quarters: the recurring restart, the project that was always almost\n  finished, the report nobody read. A year of data makes these visible in a way a month cannot.\n\n  ## The through-line\n  In one paragraph: what was this year actually about? Not the plan \u2014 the evidence.\n\n  ## Next year''s question\n  The single question the next year should answer. One question, argued for.\n\nBUDGET: at most 15 tool calls. No new research.\n\nRULES:\n  - Four quarterlies in, one page out. Compression is the deliverable.\n  - Do not flatter the record. An honest bad year is more useful than a padded one.\n\nSHELL RULES \u2014 you are unattended, so keep every command small and reviewable:\n  - NEVER inline a multi-line script (no heredocs). Write it to a file with write_file, then\n    run that file.\n  - One command does one thing. Cap output: head, tail -n, wc -l, --quiet.\n  - Use native paths (/home/iconbaypark2900/...). The filesystem MCP server sees this machine''s\n    home as /data/home instead, so its paths and shell paths are NOT interchangeable \u2014 prefer\n    shell for files, and only use qdrant through MCP.\n  - /home/iconbaypark2900/OpenWorker/knowledge is a WRITABLE ROOT of this session. Use the normal file\n    tools on it with absolute paths \u2014 read_file, write_file, list_files all work there, and\n    they are more reliable than shell redirection. Shell is for git, sqlite, find and curl.\n\nCONTINUITY \u2014 do this FIRST, before any searching:\n  1. list_files in your workspace and read the 1-2 most recent prior outputs of this\n     same job (they share this file-naming pattern).\n  2. Carry forward what is still live, mark what has closed or been resolved, and spend\n     your search budget on what is genuinely NEW since then.\n  3. If something you reported before has changed state, say so explicitly \u2014 \"X, first\n     flagged <date>, is now <state>\" is worth more than rediscovering X as if it were new.\n  4. Never re-report an unchanged item as a fresh finding.\nThis job runs on a schedule and its outputs accumulate; the value is in the running\nrecord, not in a fresh cold start every time.\n\nFOCUS \u2014 do this before anything else:\n  1. read_file FOCUS.md in your own workspace. It is rewritten every Monday from what I\n     actually worked on: the projects in play, the open questions, and what I have parked.\n  2. Tag every item you report ON-FOCUS or ADJACENT. ON-FOCUS bears on a project or open\n     question named in FOCUS.md; ADJACENT does not, but is worth knowing anyway.\n  3. Lead with ON-FOCUS. Keep the ADJACENT ones \u2014 being shown only what I already care about\n     is exactly how I get stuck \u2014 but cap them at three and put them last.\n  4. If FOCUS.md is missing, say so in one line and treat everything as ADJACENT.", "schedule": {"kind": "cron", "cron": "0 8 1 1 *", "fire_at": null, "timezone": "local"}, "workspace": "/home/iconbaypark2900/openworker-tasks/__task__task-b5517950bb", "origin_surface": "cowork", "origin_session_id": "", "agent": "repo-ops", "id": "task-b5517950bb", "task_session_id": "__task__task-b5517950bb", "model": null, "notify_on_completion": true, "notify_target": null, "always_allowed_tools": ["brain_note", "brain_recall", "grep", "list_files", "mcp__qdrant__qdrant-qdrant-find", "mcp__qdrant__qdrant-qdrant-store", "read_file", "read_file_lines", "remember", "run_shell", "todo_write", "write_file"], "always_allowed_commands": [], "enabled": true, "created_at": 1787415295.9178355, "updated_at": 1787488295.089041, "next_run": 1798804800.0, "last_run": null, "last_status": null, "run_count": 0, "max_runs": null, "seen_runs_at": 0.0}');
INSERT INTO scheduled_tasks VALUES('task-db9b445c7a',1,1788161400.0,'{"title": "Focus \u2014 derive from the week''s work", "instructions": "Work out what I am ACTUALLY pursuing right now, from evidence, and write it to\n/home/iconbaypark2900/OpenWorker/knowledge/FOCUS.md. Every other automation reads that file and sorts its findings by it, so this\njob is the one that decides what \"on focus\" means for the week. Infer from what I did \u2014 never from\nwhat I once said I would do.\n\nMETHOD \u2014 evidence first, in this order:\n  1. Repositories. Find them: `find /home/iconbaypark2900 -maxdepth 2 -name .git -type d | head -40`.\n     For each, `git -C <repo> log --since=\"14 days ago\" --pretty=format:''%ad %s'' --date=short | head -20`.\n     A repo with no commits in 14 days is NOT in focus, however important it looks.\n     Count AUTHORSHIP, not commits: `git -C <repo> log --since=\"14 days ago\" --pretty=''%an'' | sort | uniq -c | sort -rn | head -3`.\n     A clone that tracks upstream (llama.cpp, for one) shows hundreds of commits by people who\n     are not me. That is a dependency I follow, never a project I am working on \u2014 exclude it.\n  2. Sessions \u2014 what I have actually been talking about:\n     `sqlite3 /home/iconbaypark2900/.config/coworker/coworker.db \"select date(updated_at), agent, n_msgs, title from sessions where archived=0 and session_id not like ''__task__%'' order by updated_at desc limit 25\"`\n     Message count is the signal: a 300-message session is a project, a 3-message one is a question.\n  3. The automations'' own recent output:\n     `find /home/iconbaypark2900 -maxdepth 3 -path ''*__task__*'' -name ''*.md'' -printf ''%T@ %p\\n'' | sort -rn | head -30`.\n     What keeps showing up is a live thread whether or not I have named it.\n  4. The PREVIOUS FOCUS.md, if one exists. Read it before writing the new one.\n\nWRITE /home/iconbaypark2900/OpenWorker/knowledge/FOCUS.md with exactly these sections:\n  ## Active \u2014 at most 5. One line each: the project, the repo/path, and THE OPEN QUESTION it is\n     currently stuck on or working through. Ranked by evidence, strongest first. Name the evidence\n     (\"41 commits, 2 sessions this week\") so a later job can tell how sure to be.\n  ## Open questions \u2014 the things I am trying to answer, extracted from session titles and commit\n     messages. These are what the Outside View job attacks, so phrase each as a real question.\n  ## Went quiet \u2014 anything in the previous FOCUS.md with no activity in 14 days, with the date it\n     was last touched. Do not delete these silently; a project going quiet is information.\n  ## Parked \u2014 carried forward VERBATIM from the previous FOCUS.md. This section is mine, not\n     yours: never add to it and never remove from it.\n\nDISTRIBUTE \u2014 the research-persona jobs cannot read outside their own workspace, so FOCUS.md has\nto be copied to them:\n  Task workspaces live under TWO bases \u2014 `~/OpenWorker` for the automations created before the\n  scratch_base pref changed, `~/openworker-tasks` for the ones after. Find them, never assume one:\n  `find /home/iconbaypark2900 -maxdepth 2 -type d -name ''__task__*'' -exec cp /home/iconbaypark2900/OpenWorker/knowledge/FOCUS.md {} \\;`\n  Then verify: `find /home/iconbaypark2900 -maxdepth 3 -name FOCUS.md -path ''*__task__*'' | wc -l`\n  and report the count. If it is smaller than the number of automations, say so.\n\nBUDGET: at most 20 tool calls. Prefer one broad git/sqlite command over ten narrow ones.\n\nRULES:\n  - Evidence or nothing. If you cannot show the commits or the sessions behind a claimed focus,\n    it does not go in Active.\n  - Five entries maximum in Active. A focus file that lists everything states nothing.\n  - Do not invent open questions. Take them from what the commits and session titles actually say.\n\nSHELL RULES \u2014 you are unattended, so keep every command small and reviewable:\n  - NEVER inline a multi-line script (no heredocs). Write it to a file with write_file, then\n    run that file.\n  - One command does one thing. Cap output: head, tail -n, wc -l, --quiet.\n  - Use native paths (/home/iconbaypark2900/...). The filesystem MCP server sees this machine''s\n    home as /data/home instead, so its paths and shell paths are NOT interchangeable \u2014 prefer\n    shell for files, and only use qdrant through MCP.\n  - /home/iconbaypark2900/OpenWorker/knowledge is a WRITABLE ROOT of this session. Use the normal file\n    tools on it with absolute paths \u2014 read_file, write_file, list_files all work there, and\n    they are more reliable than shell redirection. Shell is for git, sqlite, find and curl.\n\nCONTINUITY \u2014 do this FIRST, before any searching:\n  1. list_files in your workspace and read the 1-2 most recent prior outputs of this\n     same job (they share this file-naming pattern).\n  2. Carry forward what is still live, mark what has closed or been resolved, and spend\n     your search budget on what is genuinely NEW since then.\n  3. If something you reported before has changed state, say so explicitly \u2014 \"X, first\n     flagged <date>, is now <state>\" is worth more than rediscovering X as if it were new.\n  4. Never re-report an unchanged item as a fresh finding.\nThis job runs on a schedule and its outputs accumulate; the value is in the running\nrecord, not in a fresh cold start every time.\n\nFOCUS \u2014 do this before anything else:\n  1. read_file FOCUS.md in your own workspace. It is rewritten every Monday from what I\n     actually worked on: the projects in play, the open questions, and what I have parked.\n  2. Tag every item you report ON-FOCUS or ADJACENT. ON-FOCUS bears on a project or open\n     question named in FOCUS.md; ADJACENT does not, but is worth knowing anyway.\n  3. Lead with ON-FOCUS. Keep the ADJACENT ones \u2014 being shown only what I already care about\n     is exactly how I get stuck \u2014 but cap them at three and put them last.\n  4. If FOCUS.md is missing, say so in one line and treat everything as ADJACENT.\n\nTHREADS \u2014 keep the durable record current, not just the dated one:\n  Your dated report is the evidence; the brain''s threads are the memory a future session reads.\n  After writing the report, for each subject that MOVED this run:\n    1. `brain_recall` the subject to find its existing thread \u2014 extend that thread, never fork a\n       near-duplicate of it.\n    2. `brain_note` one entry: what changed, with the specifics, and `source` set to the file you\n       just wrote.\n    3. Pass `now` ONLY if the subject''s current state actually changed. That line is what keeps a\n       stale claim from being retrieved later as if it were still true.\n  A quiet run notes nothing. Inventing movement to have something to record is worse than silence.\n", "schedule": {"kind": "cron", "cron": "30 3 * * 1", "fire_at": null, "timezone": "local"}, "workspace": "/home/iconbaypark2900/openworker-tasks/__task__task-db9b445c7a", "origin_surface": "cowork", "origin_session_id": "", "agent": "repo-ops", "id": "task-db9b445c7a", "task_session_id": "__task__task-db9b445c7a", "model": null, "notify_on_completion": true, "notify_target": null, "always_allowed_tools": ["brain_note", "brain_recall", "grep", "list_files", "read_file", "read_file_lines", "remember", "run_shell", "todo_write", "write_file"], "always_allowed_commands": [], "enabled": true, "created_at": 1787415295.905548, "updated_at": 1787557542.11976, "next_run": 1788161400.0, "last_run": 1787556621.2848835, "last_status": "ok", "run_count": 1, "max_runs": null, "seen_runs_at": 0.0}');
INSERT INTO scheduled_tasks VALUES('task-092a6d85f2',1,1788169500.0,'{"title": "Grant + funding digest", "instructions": "Find funding I could apply for, based on my resume.\n\nYour resume is staged in your own workspace as resume.txt (plain text, already extracted from the PDF) \u2014 read it with your file tools, by that plain filename, and use it to establish background, seniority, technical domain and eligibility.\n\nDo NOT use run_shell, ls, cat, curl or a Python script, and do not try to reach into ~/Documents/ \u2014 you run unattended and cannot see outside this workspace, so any shell command stops the run to wait for a human and nothing gets written. Web search IS allowed and needs no approval.\n\nWORK, DON''T NARRATE: do not end your turn to describe what you are about to do. Carry each step through. The run is not finished until the output file exists in this workspace \u2014 write it as your final action, every time, even if some step failed. A file that records \"search returned nothing useful for X\" is a success; no file at all is a failure.\n\nWHAT TO SEARCH FOR \u2014 money to pursue my own work, tagged by track:\n\n[RESEARCH] and [FELLOWSHIP] \u2014 NSF, DOE, NIH, DARPA, Grants.gov listings, independent-researcher fellowships, AI safety and compute-access grant programs.\n\n[SBIR] and [STARTUP] \u2014 SBIR/STTR solicitations across agencies, state innovation and technology funds, non-dilutive startup funding, accelerators with a grant component.\n\nA [FELLOWSHIP] here means funding for my own project with no employer. Salaried fellowships and residencies where I would work for an organisation belong to the daily job automation, not this digest \u2014 skip them.\n\nFor each opportunity: name, funder, award size, deadline, eligibility requirements, link, and one honest sentence on whether I actually qualify. Be direct when eligibility is a stretch \u2014 many programs require an academic institution, a registered company, PI status, or prior awards, and saying so is more useful than an optimistic listing.\n\nSort by deadline proximity, soonest first. Drop anything already closed. Flag anything due within 14 days as urgent at the top.\n\nSave as grants-YYYY-week-WW.md.\n\nCONTINUITY \u2014 do this FIRST, before any searching:\n  1. list_files in your workspace and read the 1-2 most recent prior outputs of this\n     same job (they share this file-naming pattern).\n  2. Carry forward what is still live, mark what has closed or been resolved, and spend\n     your search budget on what is genuinely NEW since then.\n  3. If something you reported before has changed state, say so explicitly \u2014 \"X, first\n     flagged <date>, is now <state>\" is worth more than rediscovering X as if it were new.\n  4. Never re-report an unchanged item as a fresh finding.\nThis job runs on a schedule and its outputs accumulate; the value is in the running\nrecord, not in a fresh cold start every time.\n\nFOCUS \u2014 do this before anything else:\n  1. read_file FOCUS.md in your own workspace. It is rewritten every Monday from what I\n     actually worked on: the projects in play, the open questions, and what I have parked.\n  2. Tag every item you report ON-FOCUS or ADJACENT. ON-FOCUS bears on a project or open\n     question named in FOCUS.md; ADJACENT does not, but is worth knowing anyway.\n  3. Lead with ON-FOCUS. Keep the ADJACENT ones \u2014 being shown only what I already care about\n     is exactly how I get stuck \u2014 but cap them at three and put them last.\n  4. If FOCUS.md is missing, say so in one line and treat everything as ADJACENT.\n", "schedule": {"kind": "cron", "cron": "45 5 * * 1", "fire_at": null, "timezone": "local"}, "workspace": "/home/iconbaypark2900/OpenWorker/__task__task-092a6d85f2", "origin_surface": "cowork", "origin_session_id": "", "agent": "research", "id": "task-092a6d85f2", "task_session_id": "__task__task-092a6d85f2", "model": null, "notify_on_completion": true, "notify_target": null, "always_allowed_tools": ["brain_note", "brain_recall", "grep", "list_files", "read_file", "read_file_lines", "remember", "todo_write", "web_fetch", "web_search", "write_file"], "always_allowed_commands": [], "enabled": true, "created_at": 1786900127.0268352, "updated_at": 1787566834.10566, "next_run": 1788169500.0, "last_run": 1787564721.4545956, "last_status": "incomplete", "run_count": 4, "max_runs": null, "seen_runs_at": 1787250251.891512}');
INSERT INTO scheduled_tasks VALUES('task-0db7112de6',1,1788168600.0,'{"title": "Weekly research corpus -> Qdrant", "instructions": "Build this week''s research corpus and store it in Qdrant so my agents can retrieve it later.\n\nTOPICS \u2014 search each one separately, do not merge them into a single query:\n  1. Quantum computing: algorithms, error correction, hardware, quantum ML\n  2. Materials science: DFT, ML interatomic potentials, crystal structure generation\n  3. ML systems: inference efficiency, quantization, MoE architectures, long context\n  4. Agents: tool use, retrieval, evaluation, multi-agent systems\n\nMETHOD \u2014 follow this order, it matters:\n  1. mcp__arxiv__arxiv-search_papers for each topic, restricted to the last 7 days.\n  2. For every paper that looks genuinely relevant, mcp__arxiv__arxiv-get_abstract to read the\n     actual abstract. Do NOT judge relevance from the title alone.\n  3. For each one you keep, mcp__qdrant__qdrant-qdrant-store with:\n       information: \"<title>. <one-sentence finding from the abstract, in your own\n                    words>. arXiv:<id>\"\n       metadata:    {\"topic\": \"<one of the four above>\", \"arxiv_id\": \"<id>\",\n                     \"date\": \"<YYYY-MM-DD>\", \"source\": \"arxiv-weekly\"}\n  4. Before storing, mcp__qdrant__qdrant-qdrant-find on the title to check it is not already\n     stored. Skip duplicates \u2014 a corpus full of near-identical entries retrieves\n     worse than a small clean one.\n  5. Write a summary to the workspace as corpus-<YYYY-MM-DD>.md listing what you\n     stored, grouped by topic, with arXiv IDs.\n\nBUDGET \u2014 hard limits:\n  - AT MOST 4 arxiv searches (one per topic) and 20 abstract reads.\n  - Store AT MOST 15 papers. Fewer good entries beat many mediocre ones; this\n    corpus is retrieved from, so noise in it degrades every future query.\n\nRULES:\n  - Only store what you actually read. A stored summary of an abstract you did not\n    open is a fabrication that will be retrieved as fact later.\n  - If mcp__arxiv__arxiv-search_papers returns nothing for a topic, say so in the summary and\n    move on. Do not fill the gap from memory.\n  - Every entry must carry a real arXiv ID copied from tool output.\n\nCONTINUITY \u2014 do this FIRST, before any searching:\n  1. list_files in your workspace and read the 1-2 most recent prior outputs of this\n     same job (they share this file-naming pattern).\n  2. Carry forward what is still live, mark what has closed or been resolved, and spend\n     your search budget on what is genuinely NEW since then.\n  3. If something you reported before has changed state, say so explicitly \u2014 \"X, first\n     flagged <date>, is now <state>\" is worth more than rediscovering X as if it were new.\n  4. Never re-report an unchanged item as a fresh finding.\nThis job runs on a schedule and its outputs accumulate; the value is in the running\nrecord, not in a fresh cold start every time.\n\nFOCUS \u2014 do this before anything else:\n  1. read_file FOCUS.md in your own workspace. It is rewritten every Monday from what I\n     actually worked on: the projects in play, the open questions, and what I have parked.\n  2. Tag every item you report ON-FOCUS or ADJACENT. ON-FOCUS bears on a project or open\n     question named in FOCUS.md; ADJACENT does not, but is worth knowing anyway.\n  3. Lead with ON-FOCUS. Keep the ADJACENT ones \u2014 being shown only what I already care about\n     is exactly how I get stuck \u2014 but cap them at three and put them last.\n  4. If FOCUS.md is missing, say so in one line and treat everything as ADJACENT.\n", "schedule": {"kind": "cron", "cron": "30 5 * * 1", "fire_at": null, "timezone": "local"}, "workspace": "/home/iconbaypark2900/OpenWorker/__task__task-0db7112de6", "origin_surface": "cowork", "origin_session_id": "", "agent": "repo-ops", "id": "task-0db7112de6", "task_session_id": "__task__task-0db7112de6", "model": null, "notify_on_completion": true, "notify_target": null, "always_allowed_tools": ["brain_note", "brain_recall", "grep", "list_files", "read_file", "read_file_lines", "remember", "run_shell", "todo_write", "web_fetch", "web_search", "write_file"], "always_allowed_commands": [], "enabled": true, "created_at": 1786986451.6855567, "updated_at": 1787568031.946886, "next_run": 1788168600.0, "last_run": 1787563821.4296806, "last_status": "incomplete", "run_count": 11, "max_runs": null, "seen_runs_at": 1787250281.6546338}');
INSERT INTO scheduled_tasks VALUES('task-78fcb8b740',1,1788342300.0,'{"title": "Outside view \u2014 argue against the current approach", "instructions": "Attack the way I am currently solving my main problem. Everything else on my schedule\ntells me more about what I am already doing; this job exists to tell me what I am not considering.\nIt runs mid-week, while there is still time to change course.\n\nPICK THE TARGET:\n  1. read_file FOCUS.md in your workspace.\n  2. Take the FIRST entry under \"## Active\" and the open question attached to it. One target per\n     run \u2014 a shallow pass over five projects is worth nothing.\n  3. Name the target and its current approach in one sentence at the top of your report, so it is\n     obvious what you are arguing against.\n\nFOUR ANGLES \u2014 search each separately, do not merge them:\n  1. ALTERNATIVE APPROACHES. How else is this problem solved? Find at least two approaches that\n     are not the one I am using, and say what each buys and costs.\n  2. PRIOR ART. Who has already solved this, and how? A library, a paper, a product, a blog post\n     from someone who hit the same wall. If it exists, using it beats rebuilding it.\n  3. THE CASE AGAINST. Find real arguments against my current approach \u2014 post-mortems, \"why we\n     moved off X\" write-ups, known failure modes. Search for the criticism explicitly; a search\n     that only returns enthusiasm was the wrong search.\n  4. THE ADJACENT FIELD. One field that is not mine and has met this problem shape before. Say\n     what transfers.\n\nCLOSE WITH TWO THINGS, both required:\n  - ONE THING TO CONSIDER ABANDONING. Name the piece of the current approach with the worst\n    effort-to-payoff ratio, and say what would replace it. If you genuinely cannot find one, say\n    \"nothing \u2014 here is why the current approach holds\" and give the reason. Never leave it blank.\n  - ONE CHEAP EXPERIMENT that would show the current approach is wrong, runnable in under an hour.\n\nBUDGET: at most 8 searches and 10 page fetches. Read the pages you cite \u2014 a snippet is a pointer,\nnot evidence.\n\nRULES:\n  - Be specific and be willing to be wrong. A hedged report that offends nobody is useless here.\n  - Argue from sources you opened, not from general impressions. Attribute every claim to its URL.\n  - Do not soften the conclusion because it is inconvenient. If the honest read is \"you are\n    building the wrong thing\", write that.\n\nWrite outside-view-<YYYY-MM-DD>.md in your workspace.\n\nFOCUS \u2014 do this before anything else:\n  1. read_file FOCUS.md in your own workspace. It is rewritten every Monday from what I\n     actually worked on: the projects in play, the open questions, and what I have parked.\n  2. Tag every item you report ON-FOCUS or ADJACENT. ON-FOCUS bears on a project or open\n     question named in FOCUS.md; ADJACENT does not, but is worth knowing anyway.\n  3. Lead with ON-FOCUS. Keep the ADJACENT ones \u2014 being shown only what I already care about\n     is exactly how I get stuck \u2014 but cap them at three and put them last.\n  4. If FOCUS.md is missing, say so in one line and treat everything as ADJACENT.", "schedule": {"kind": "cron", "cron": "45 5 * * 3", "fire_at": null, "timezone": "local"}, "workspace": "/home/iconbaypark2900/openworker-tasks/__task__task-78fcb8b740", "origin_surface": "cowork", "origin_session_id": "", "agent": "research", "id": "task-78fcb8b740", "task_session_id": "__task__task-78fcb8b740", "model": null, "notify_on_completion": true, "notify_target": null, "always_allowed_tools": ["brain_note", "brain_recall", "grep", "list_files", "read_file", "read_file_lines", "remember", "todo_write", "web_fetch", "web_search", "write_file"], "always_allowed_commands": [], "enabled": true, "created_at": 1787415295.91519, "updated_at": 1787742268.324694, "next_run": 1788342300.0, "last_run": 1787737503.2004411, "last_status": "ok", "run_count": 1, "max_runs": null, "seen_runs_at": 0.0}');
INSERT INTO scheduled_tasks VALUES('task-4f5c834615',1,1788172200.0,'{"title": "Weekly review \u2014 what moved, what is stuck", "instructions": "Write the week''s review: what moved, what is still open, and what I keep being told\nand keep ignoring. This is the level where the daily briefs become a decision.\n\nREAD, in this order:\n  1. /home/iconbaypark2900/OpenWorker/knowledge/FOCUS.md \u2014 this week''s focus, written a few hours ago.\n  2. The week''s automation output:\n     `find /home/iconbaypark2900 -maxdepth 3 -path ''*__task__*'' -name ''*.md'' -mtime -7 | head -40`\n     (both scratch bases: ~/OpenWorker and ~/openworker-tasks)\n     Read the ones whose names say they are briefs; skip FOCUS.md copies.\n  3. The previous weekly review in /home/iconbaypark2900/OpenWorker/knowledge/reports/weekly/ \u2014 you are continuing a record.\n  4. The KB, for anything the files above do not cover: mcp__qdrant__qdrant-qdrant-find on each Active\n     project named in FOCUS.md. At most 5 queries.\n\nWRITE /home/iconbaypark2900/OpenWorker/knowledge/reports/weekly/<YYYY>-W<ww>.md with these four sections, in this order:\n\n  ## Moved\n  What actually changed this week, per Active project \u2014 commits landed, questions answered,\n  things that broke and got fixed. Each line names its evidence.\n\n  ## Still open\n  Questions from FOCUS.md that are still questions. For each, say what would close it.\n\n  ## Unexamined\n  THIS IS THE POINT OF THE JOB. Anything that has been reported three or more times across the\n  daily outputs and has never changed state: the same broken dependency, the same drifted spec,\n  the same paper topic recurring, the same job or grant deadline approaching untouched.\n  Find them by grepping the accumulated outputs, not from memory:\n    `grep -rhoi ''<candidate phrase>'' --include=''*.md'' /home/iconbaypark2900/OpenWorker /home/iconbaypark2900/openworker-tasks | wc -l`\n  For each: how many times it has appeared, when it first appeared, and the smallest action that\n  would end it. Say plainly if this section is empty \u2014 do not manufacture entries.\n\n  ## Decisions waiting on me\n  At most three. Each one a question I can answer yes or no, with the consequence of each answer.\n\nBUDGET: at most 30 tool calls. Reading 12 files well beats skimming 40.\n\nRULES:\n  - Every claim traces to a file you read this run. No summarising from memory of last week.\n  - \"Nothing moved on X\" is a finding worth writing, not a gap to paper over.\n  - Do not restate the daily briefs. If a line would be equally true in yesterday''s brief, cut it.\n\nSHELL RULES \u2014 you are unattended, so keep every command small and reviewable:\n  - NEVER inline a multi-line script (no heredocs). Write it to a file with write_file, then\n    run that file.\n  - One command does one thing. Cap output: head, tail -n, wc -l, --quiet.\n  - Use native paths (/home/iconbaypark2900/...). The filesystem MCP server sees this machine''s\n    home as /data/home instead, so its paths and shell paths are NOT interchangeable \u2014 prefer\n    shell for files, and only use qdrant through MCP.\n  - /home/iconbaypark2900/OpenWorker/knowledge is a WRITABLE ROOT of this session. Use the normal file\n    tools on it with absolute paths \u2014 read_file, write_file, list_files all work there, and\n    they are more reliable than shell redirection. Shell is for git, sqlite, find and curl.\n\nCONTINUITY \u2014 do this FIRST, before any searching:\n  1. list_files in your workspace and read the 1-2 most recent prior outputs of this\n     same job (they share this file-naming pattern).\n  2. Carry forward what is still live, mark what has closed or been resolved, and spend\n     your search budget on what is genuinely NEW since then.\n  3. If something you reported before has changed state, say so explicitly \u2014 \"X, first\n     flagged <date>, is now <state>\" is worth more than rediscovering X as if it were new.\n  4. Never re-report an unchanged item as a fresh finding.\nThis job runs on a schedule and its outputs accumulate; the value is in the running\nrecord, not in a fresh cold start every time.\n\nFOCUS \u2014 do this before anything else:\n  1. read_file FOCUS.md in your own workspace. It is rewritten every Monday from what I\n     actually worked on: the projects in play, the open questions, and what I have parked.\n  2. Tag every item you report ON-FOCUS or ADJACENT. ON-FOCUS bears on a project or open\n     question named in FOCUS.md; ADJACENT does not, but is worth knowing anyway.\n  3. Lead with ON-FOCUS. Keep the ADJACENT ones \u2014 being shown only what I already care about\n     is exactly how I get stuck \u2014 but cap them at three and put them last.\n  4. If FOCUS.md is missing, say so in one line and treat everything as ADJACENT.\n\nTHREADS \u2014 keep the durable record current, not just the dated one:\n  Your dated report is the evidence; the brain''s threads are the memory a future session reads.\n  After writing the report, for each subject that MOVED this run:\n    1. `brain_recall` the subject to find its existing thread \u2014 extend that thread, never fork a\n       near-duplicate of it.\n    2. `brain_note` one entry: what changed, with the specifics, and `source` set to the file you\n       just wrote.\n    3. Pass `now` ONLY if the subject''s current state actually changed. That line is what keeps a\n       stale claim from being retrieved later as if it were still true.\n  A quiet run notes nothing. Inventing movement to have something to record is worse than silence.\n", "schedule": {"kind": "cron", "cron": "30 6 * * 1", "fire_at": null, "timezone": "local"}, "workspace": "/home/iconbaypark2900/openworker-tasks/__task__task-4f5c834615", "origin_surface": "cowork", "origin_session_id": "", "agent": "repo-ops", "id": "task-4f5c834615", "task_session_id": "__task__task-4f5c834615", "model": null, "notify_on_completion": true, "notify_target": null, "always_allowed_tools": ["brain_note", "brain_recall", "grep", "list_files", "mcp__qdrant__qdrant-qdrant-find", "mcp__qdrant__qdrant-qdrant-store", "read_file", "read_file_lines", "remember", "run_shell", "todo_write", "write_file"], "always_allowed_commands": [], "enabled": true, "created_at": 1787415295.9131181, "updated_at": 1787834260.041994, "next_run": 1788172200.0, "last_run": 1787567421.5195, "last_status": "incomplete", "run_count": 1, "max_runs": null, "seen_runs_at": 1787834260.0419922}');
INSERT INTO scheduled_tasks VALUES('task-c6cf366b90',1,1788165300.0,'{"title": "Job matches + tailored drafts", "instructions": "Find roles worth applying for, based on my resume.\n\nYour resume is staged in your own workspace as resume.txt (plain text, already extracted from the PDF) \u2014 read it with your file tools, by that plain filename, and use it to establish background, seniority, technical domain and eligibility.\n\nDo NOT use run_shell, ls, cat, curl or a Python script, and do not try to reach into ~/Documents/ \u2014 you run unattended and cannot see outside this workspace, so any shell command stops the run to wait for a human and nothing gets written. Web search IS allowed and needs no approval.\n\nWORK, DON''T NARRATE: do not end your turn to describe what you are about to do. Carry each step through. The run is not finished until the output file exists in this workspace \u2014 write it as your final action, every time, even if some step failed. A file that records \"search returned nothing useful for X\" is a success; no file at all is a failure.\n\nWHAT TO SEARCH FOR \u2014 two categories, both are positions you hold and get paid for:\n1. Standard openings matching the profile \u2014 seniority, domain, technical strengths.\n2. Fellowships and residencies that function as jobs: AI/ML residencies, research fellowships with a salary or stipend, industry fellowships, government and think-tank technical fellowships. Include these even when the title says \"fellow\" rather than \"engineer\".\n\nDo NOT include funding-only fellowships here \u2014 grants that pay for your own independent work, with no employer, belong to the separate weekly grant digest. The test is simple: if you would be working *for* an organisation, it goes here; if you would be receiving money to pursue your own project, it does not.\n\nSearch openings posted in roughly the last day.\n\nFor each match record: organisation, role title, whether it is a standard role or a fellowship/residency, location and remote policy, salary or stipend if stated, link, and a fit assessment naming the specific evidence in my resume that supports it plus any genuine gaps against the requirements. Fellowships often have fixed cohort deadlines \u2014 record the deadline whenever one exists, since those close on a date rather than when filled.\n\nRank by fit and keep only plausible matches. Five strong matches beat twenty padded ones; if the day is thin, return three and say so.\n\nFor the top 3 matches, create a drafts/ subfolder containing, per role:\n- cover-letter-<organisation>.md \u2014 tailored to that specific posting, using real evidence from the resume and referencing what the organisation actually does.\n- resume-tweaks-<organisation>.md \u2014 specific edits that would strengthen this application: which bullets to lead with, what to rephrase in the posting''s language, what to cut.\n\nNever invent experience, credentials, or dates that are not in the resume.\n\nSave the shortlist as jobs-YYYY-MM-DD.md, fellowships and standard roles clearly labelled. Do not submit an application anywhere or contact anyone \u2014 produce the files only.\n\nCONTINUITY \u2014 do this FIRST, before any searching:\n  1. list_files in your workspace and read the 1-2 most recent prior outputs of this\n     same job (they share this file-naming pattern).\n  2. Carry forward what is still live, mark what has closed or been resolved, and spend\n     your search budget on what is genuinely NEW since then.\n  3. If something you reported before has changed state, say so explicitly \u2014 \"X, first\n     flagged <date>, is now <state>\" is worth more than rediscovering X as if it were new.\n  4. Never re-report an unchanged item as a fresh finding.\nThis job runs on a schedule and its outputs accumulate; the value is in the running\nrecord, not in a fresh cold start every time.\n\nFOCUS \u2014 do this before anything else:\n  1. read_file FOCUS.md in your own workspace. It is rewritten every Monday from what I\n     actually worked on: the projects in play, the open questions, and what I have parked.\n  2. Tag every item you report ON-FOCUS or ADJACENT. ON-FOCUS bears on a project or open\n     question named in FOCUS.md; ADJACENT does not, but is worth knowing anyway.\n  3. Lead with ON-FOCUS. Keep the ADJACENT ones \u2014 being shown only what I already care about\n     is exactly how I get stuck \u2014 but cap them at three and put them last.\n  4. If FOCUS.md is missing, say so in one line and treat everything as ADJACENT.\n", "schedule": {"kind": "cron", "cron": "35 4 * * *", "fire_at": null, "timezone": "local"}, "workspace": "/home/iconbaypark2900/OpenWorker/__task__task-c6cf366b90", "origin_surface": "cowork", "origin_session_id": "", "agent": "research", "id": "task-c6cf366b90", "task_session_id": "__task__task-c6cf366b90", "model": null, "notify_on_completion": true, "notify_target": null, "always_allowed_tools": ["brain_note", "brain_recall", "grep", "list_files", "read_file", "read_file_lines", "remember", "todo_write", "web_fetch", "web_search", "write_file"], "always_allowed_commands": [], "enabled": true, "created_at": 1786900127.0179763, "updated_at": 1788103272.895422, "next_run": 1788165300.0, "last_run": 1788103270.0695932, "last_status": "incomplete", "run_count": 18, "max_runs": null, "seen_runs_at": 1787834160.51539}');
INSERT INTO scheduled_tasks VALUES('task-c685e22a0b',1,1788168000.0,'{"title": "Morning news briefing", "instructions": "Write me a 5-bullet briefing on what actually happened in the last 24 hours.\n\nSCOPE \u2014 in priority order. Lead with whatever genuinely moved:\n  1. AI / ML industry: model releases, capability results, major funding and\n     acquisitions, compute and chip supply, notable safety or policy incidents.\n  2. Local-inference and open-weights specifically: llama.cpp / ollama / vLLM,\n     new open weights, quantization and hardware support (AMD ROCm especially \u2014\n     this machine runs a Strix Halo iGPU).\n  3. World news that a US-based engineer should not be blindsided by: major\n     geopolitical events, market-moving macro, significant policy changes.\n\nMETHOD:\n  1. web_search for each of the three areas separately \u2014 do not merge them into one\n     query, the results collapse into whatever is loudest.\n  2. web_fetch and actually READ at least two sources before writing. A search snippet\n     is a pointer, not evidence.\n  3. Prefer the primary source (the release post, the filing, the announcement) over\n     an aggregator reporting on it.\n\nBUDGET: AT MOST 5 searches and 4 page fetches.\n\nFOR EACH BULLET: one bold claim sentence, then the specific detail that makes it matter\n(the number, the name, the date), then the source in parentheses. Attribute every\nnon-obvious figure to a page you actually opened.\n\nRULES:\n  - Exactly 5 bullets. If the day is genuinely thin, say so in one line and give 3 \u2014\n    padding a slow day with filler makes the briefing worthless to skim.\n  - Never state a figure, date, or version you did not read directly. No reconstructing\n    plausible headlines from memory.\n  - Skip anything you already reported in a prior briefing unless it materially changed.\n\nSave as morning-briefing-YYYY-MM-DD.md. Writing that file is the deliverable \u2014 a run\nthat ends without it has failed.\n\nCONTINUITY \u2014 do this FIRST, before any searching:\n  1. list_files in your workspace and read the 1-2 most recent prior outputs of this\n     same job (they share this file-naming pattern).\n  2. Carry forward what is still live, mark what has closed or been resolved, and spend\n     your search budget on what is genuinely NEW since then.\n  3. If something you reported before has changed state, say so explicitly \u2014 \"X, first\n     flagged <date>, is now <state>\" is worth more than rediscovering X as if it were new.\n  4. Never re-report an unchanged item as a fresh finding.\nThis job runs on a schedule and its outputs accumulate; the value is in the running\nrecord, not in a fresh cold start every time.\n\nFOCUS \u2014 do this before anything else:\n  1. read_file FOCUS.md in your own workspace. It is rewritten every Monday from what I\n     actually worked on: the projects in play, the open questions, and what I have parked.\n  2. Tag every item you report ON-FOCUS or ADJACENT. ON-FOCUS bears on a project or open\n     question named in FOCUS.md; ADJACENT does not, but is worth knowing anyway.\n  3. Lead with ON-FOCUS. Keep the ADJACENT ones \u2014 being shown only what I already care about\n     is exactly how I get stuck \u2014 but cap them at three and put them last.\n  4. If FOCUS.md is missing, say so in one line and treat everything as ADJACENT.\n", "schedule": {"kind": "cron", "cron": "20 5 * * *", "fire_at": null, "timezone": "local"}, "workspace": "/home/iconbaypark2900/OpenWorker/__task__task-c685e22a0b", "origin_surface": "cowork", "origin_session_id": "", "agent": "research", "id": "task-c685e22a0b", "task_session_id": "__task__task-c685e22a0b", "model": null, "notify_on_completion": true, "notify_target": null, "always_allowed_tools": ["brain_note", "brain_recall", "grep", "list_files", "read_file", "read_file_lines", "remember", "todo_write", "web_fetch", "web_search", "write_file"], "always_allowed_commands": [], "enabled": true, "created_at": 1786891896.2770672, "updated_at": 1788103273.011208, "next_run": 1788168000.0, "last_run": 1788103270.0698311, "last_status": "incomplete", "run_count": 21, "max_runs": null, "seen_runs_at": 1787834279.0388746}');
INSERT INTO scheduled_tasks VALUES('task-f471043f3e',1,1788164100.0,'{"title": "Dependency & breakage watch", "instructions": "Check whether anything in the stack I actually run has broken or moved.\n\nWATCH LIST \u2014 these exact projects, at these installed versions. Do not widen it;\na generic news sweep is noise.\n\n  ROCm                7.1.0        (gfx1151 / Strix Halo)\n  llama.cpp           4df29be4f    (Vulkan + HIP builds)\n  ollama              0.32.14\n  torch               2.11.0+rocm7.13.0   (from the gfx1151 nightly index)\n  transformers        5.5.0\n  unsloth             AMD/gfx1151 support\n  LibreChat           librechat-dev:latest\n  OpenWorker          andrewyng/openworker\n  kernel              7.0.0-29-generic\n\nFOR EACH \u2014 search with tavily-tavily_search and, where it is a library,\ncontext7-query-docs:\n  1. Has a newer version shipped since the one above?\n  2. Are there BREAKING changes, regressions, or CVEs affecting it?\n  3. Anything specific to gfx1151 / Strix Halo / RDNA?\n\nWHAT MATTERS MOST \u2014 prioritise these, they have already cost real time here:\n  - torch/ROCm wheel changes that silently substitute CUDA builds\n  - llama.cpp build-dependency changes (it began requiring spirv-headers)\n  - CMake/toolchain incompatibilities (CMake 4.x rejects the hipcc wrapper)\n  - transformers major-version breaks in models loaded with trust_remote_code\n  - gfx1151 driver bugs (a ROCm 7.1 bug segfaults torch._grouped_mm)\n\nBUDGET: AT MOST 6 searches. Write findings to breakage-<YYYY-MM-DD>.md, ordered\nby how likely each is to break this machine. Say plainly when nothing changed --\n\"no changes found for X\" is a useful result, and padding is not.\n\nRULES:\n  - Never state a version number from memory. Retrieve it or omit it.\n  - Cite the release note or advisory URL you actually opened.\n  - A search returning nothing means nothing changed, NOT that you should\n    reconstruct plausible release notes.\n\nCONTINUITY \u2014 do this FIRST, before any searching:\n  1. list_files in your workspace and read the 1-2 most recent prior outputs of this\n     same job (they share this file-naming pattern).\n  2. Carry forward what is still live, mark what has closed or been resolved, and spend\n     your search budget on what is genuinely NEW since then.\n  3. If something you reported before has changed state, say so explicitly \u2014 \"X, first\n     flagged <date>, is now <state>\" is worth more than rediscovering X as if it were new.\n  4. Never re-report an unchanged item as a fresh finding.\nThis job runs on a schedule and its outputs accumulate; the value is in the running\nrecord, not in a fresh cold start every time.\n\nFOCUS \u2014 do this before anything else:\n  1. read_file FOCUS.md in your own workspace. It is rewritten every Monday from what I\n     actually worked on: the projects in play, the open questions, and what I have parked.\n  2. Tag every item you report ON-FOCUS or ADJACENT. ON-FOCUS bears on a project or open\n     question named in FOCUS.md; ADJACENT does not, but is worth knowing anyway.\n  3. Lead with ON-FOCUS. Keep the ADJACENT ones \u2014 being shown only what I already care about\n     is exactly how I get stuck \u2014 but cap them at three and put them last.\n  4. If FOCUS.md is missing, say so in one line and treat everything as ADJACENT.\n", "schedule": {"kind": "cron", "cron": "15 4 * * *", "fire_at": null, "timezone": "local"}, "workspace": "/home/iconbaypark2900/OpenWorker/__task__task-f471043f3e", "origin_surface": "cowork", "origin_session_id": "", "agent": "research", "id": "task-f471043f3e", "task_session_id": "__task__task-f471043f3e", "model": null, "notify_on_completion": true, "notify_target": null, "always_allowed_tools": ["brain_note", "brain_recall", "grep", "list_files", "read_file", "read_file_lines", "remember", "todo_write", "web_fetch", "web_search", "write_file"], "always_allowed_commands": [], "enabled": true, "created_at": 1786987187.2846577, "updated_at": 1788103273.016793, "next_run": 1788164100.0, "last_run": 1788103270.0694308, "last_status": "incomplete", "run_count": 17, "max_runs": null, "seen_runs_at": 1787250201.4933465}');
INSERT INTO scheduled_tasks VALUES('task-1b2c4d3f13',1,1788163200.0,'{"title": "Research papers \u2014 quantum, ML, recursive self-improvement", "instructions": "Find research papers published in the last 24 hours across three topics:\n1. Quantum computing \u2014 algorithms, error correction, hardware, quantum ML.\n2. Machine learning \u2014 architectures, training methods, reasoning, evaluation.\n3. Recursive self-improvement \u2014 self-modifying agents, automated AI research, models that improve their own capabilities, scaling of autonomous research loops.\n\nHOW TO SEARCH \u2014 this matters, read it before starting:\nUse the arxiv MCP tools directly: search_papers to find candidates, get_abstract to read them, semantic_search when a keyword query is too blunt. They are already connected and need no setup.\n\nDo NOT write a Python script, and do NOT use run_shell or curl to query the arXiv API. You are running unattended on a schedule: every shell command stops and waits for a human to approve it, so a script-based approach stalls this run indefinitely and produces nothing. The MCP tools do not require approval. If an arxiv tool returns nothing useful, use the web search tool \u2014 never fall back to shell.\n\nFor each paper give: title, authors, link, and 2-3 sentences on what is genuinely new and why it matters \u2014 your own read, not the abstract restated.\n\nBe selective. Skip incremental variations. If a topic has nothing genuinely new today, say so in one line rather than padding the list.\n\nSave the result as papers-YYYY-MM-DD.md in the task workspace, grouped by the three topics, most significant first within each. Writing that file is the deliverable \u2014 do not finish the run without it.\n\nCONTINUITY \u2014 do this FIRST, before any searching:\n  1. list_files in your workspace and read the 1-2 most recent prior outputs of this\n     same job (they share this file-naming pattern).\n  2. Carry forward what is still live, mark what has closed or been resolved, and spend\n     your search budget on what is genuinely NEW since then.\n  3. If something you reported before has changed state, say so explicitly \u2014 \"X, first\n     flagged <date>, is now <state>\" is worth more than rediscovering X as if it were new.\n  4. Never re-report an unchanged item as a fresh finding.\nThis job runs on a schedule and its outputs accumulate; the value is in the running\nrecord, not in a fresh cold start every time.\n\nFOCUS \u2014 do this before anything else:\n  1. read_file FOCUS.md in your own workspace. It is rewritten every Monday from what I\n     actually worked on: the projects in play, the open questions, and what I have parked.\n  2. Tag every item you report ON-FOCUS or ADJACENT. ON-FOCUS bears on a project or open\n     question named in FOCUS.md; ADJACENT does not, but is worth knowing anyway.\n  3. Lead with ON-FOCUS. Keep the ADJACENT ones \u2014 being shown only what I already care about\n     is exactly how I get stuck \u2014 but cap them at three and put them last.\n  4. If FOCUS.md is missing, say so in one line and treat everything as ADJACENT.\n", "schedule": {"kind": "cron", "cron": "0 4 * * *", "fire_at": null, "timezone": "local"}, "workspace": "/home/iconbaypark2900/OpenWorker/__task__task-1b2c4d3f13", "origin_surface": "cowork", "origin_session_id": "", "agent": "research", "id": "task-1b2c4d3f13", "task_session_id": "__task__task-1b2c4d3f13", "model": null, "notify_on_completion": true, "notify_target": null, "always_allowed_tools": ["brain_note", "brain_recall", "grep", "list_files", "read_file", "read_file_lines", "remember", "todo_write", "web_fetch", "web_search", "write_file"], "always_allowed_commands": [], "enabled": true, "created_at": 1786900126.999427, "updated_at": 1788103273.026624, "next_run": 1788163200.0, "last_run": 1788103270.0647516, "last_status": "incomplete", "run_count": 20, "max_runs": null, "seen_runs_at": 1787834003.0018084}');
INSERT INTO scheduled_tasks VALUES('task-717e4360ea',1,1788167100.0,'{"title": "Repo activity brief", "instructions": "Summarise what moved in my repositories in the last 24 hours.\n\nREPOS \u2014 check these, they are the ones under active work:\n  iconbaypark2900/dcode-stack          iconbaypark2900/workstation-stack\n  iconbaypark2900/ragtradesystem       iconbaypark2900/sigma\n  iconbaypark2900/liaison-agentSystem  iconbaypark2900/qgg_research\n  iconbaypark2900/materialScience      iconbaypark2900/setup\n  iconbaypark2900/polymarket_btc       iconbaypark2900/sourcelab_ai_production_scaffold\n\nMETHOD:\n  1. github-list_commits per repo, last 24h.\n  2. For repos with commits, github-get_file_contents only if a message is too\n     terse to summarise honestly. Do not guess what a commit did from its subject.\n  3. Group the report by repo. For each: what changed and why it appears to matter.\n\nALSO FLAG:\n  - Repos with NO commits in 7+ days that had recent activity before that --\n    stalled work is worth surfacing.\n  - Commits whose message is only \"WIP\" or similar, with no other context.\n\nBUDGET: AT MOST 12 tool calls. If you hit the limit, say which repos you did not\nreach rather than silently truncating.\n\nWrite to repo-activity-<YYYY-MM-DD>.md. If nothing changed anywhere, say exactly\nthat in one line -- do not pad it.\n\nCONTINUITY \u2014 do this FIRST, before any searching:\n  1. list_files in your workspace and read the 1-2 most recent prior outputs of this\n     same job (they share this file-naming pattern).\n  2. Carry forward what is still live, mark what has closed or been resolved, and spend\n     your search budget on what is genuinely NEW since then.\n  3. If something you reported before has changed state, say so explicitly \u2014 \"X, first\n     flagged <date>, is now <state>\" is worth more than rediscovering X as if it were new.\n  4. Never re-report an unchanged item as a fresh finding.\nThis job runs on a schedule and its outputs accumulate; the value is in the running\nrecord, not in a fresh cold start every time.\n\nFOCUS \u2014 do this before anything else:\n  1. read_file FOCUS.md in your own workspace. It is rewritten every Monday from what I\n     actually worked on: the projects in play, the open questions, and what I have parked.\n  2. Tag every item you report ON-FOCUS or ADJACENT. ON-FOCUS bears on a project or open\n     question named in FOCUS.md; ADJACENT does not, but is worth knowing anyway.\n  3. Lead with ON-FOCUS. Keep the ADJACENT ones \u2014 being shown only what I already care about\n     is exactly how I get stuck \u2014 but cap them at three and put them last.\n  4. If FOCUS.md is missing, say so in one line and treat everything as ADJACENT.\n", "schedule": {"kind": "cron", "cron": "5 5 * * *", "fire_at": null, "timezone": "local"}, "workspace": "/home/iconbaypark2900/OpenWorker/__task__task-717e4360ea", "origin_surface": "cowork", "origin_session_id": "", "agent": "repo-ops", "id": "task-717e4360ea", "task_session_id": "__task__task-717e4360ea", "model": null, "notify_on_completion": true, "notify_target": null, "always_allowed_tools": ["brain_note", "brain_recall", "grep", "list_files", "mcp__github__github-get_file_contents", "mcp__github__github-list_commits", "read_file", "read_file_lines", "remember", "run_shell", "todo_write", "web_fetch", "web_search", "write_file"], "always_allowed_commands": [], "enabled": true, "created_at": 1786987187.2849042, "updated_at": 1788103273.085101, "next_run": 1788167100.0, "last_run": 1788103270.0697112, "last_status": "incomplete", "run_count": 19, "max_runs": null, "seen_runs_at": 1787869253.228631}');
INSERT INTO scheduled_tasks VALUES('task-c708f5430e',1,1788687000.0,'{"title": "Spec drift check", "instructions": "Audit my dcode-stack specs against their implementations and report drift.\n\nSCOPE: every slice under ~/dcode-stack/slices/. Each has a SPEC.md and code.\n\nMETHOD \u2014 read BOTH, always:\n  1. filesystem-directory_tree on ~/dcode-stack/slices to enumerate them.\n  2. For each slice: filesystem-read_text_file the SPEC.md, then the\n     implementation it describes.\n  3. Compare. Report: what the spec REQUIRES, what the code DOES, whether they\n     agree.\n\nFAIL CLOSED. If you could not read a file, that slice is UNKNOWN, not passing. An\nunverified claim of conformance is worse than saying you could not check -- it\ngets trusted.\n\nPRIORITISE the invariants these specs care about, which are mostly about silent\nfailure:\n  - \"malformed input MUST be fatal, never silently coerced or skipped\"\n  - guards that must not be silently dropped\n  - values that must raise rather than be coerced\n\nBUDGET: AT MOST 15 tool calls. Cover as many slices as that allows and list which\nyou did not reach. Partial coverage stated honestly beats full coverage claimed.\n\nWrite to spec-drift-<YYYY-MM-DD>.md with three sections: DRIFT (spec and code\ndisagree), UNKNOWN (could not verify), OK (verified matching). Put DRIFT first.\n\nCONTINUITY \u2014 do this FIRST, before any searching:\n  1. list_files in your workspace and read the 1-2 most recent prior outputs of this\n     same job (they share this file-naming pattern).\n  2. Carry forward what is still live, mark what has closed or been resolved, and spend\n     your search budget on what is genuinely NEW since then.\n  3. If something you reported before has changed state, say so explicitly \u2014 \"X, first\n     flagged <date>, is now <state>\" is worth more than rediscovering X as if it were new.\n  4. Never re-report an unchanged item as a fresh finding.\nThis job runs on a schedule and its outputs accumulate; the value is in the running\nrecord, not in a fresh cold start every time.\n\nFOCUS \u2014 do this before anything else:\n  1. read_file FOCUS.md in your own workspace. It is rewritten every Monday from what I\n     actually worked on: the projects in play, the open questions, and what I have parked.\n  2. Tag every item you report ON-FOCUS or ADJACENT. ON-FOCUS bears on a project or open\n     question named in FOCUS.md; ADJACENT does not, but is worth knowing anyway.\n  3. Lead with ON-FOCUS. Keep the ADJACENT ones \u2014 being shown only what I already care about\n     is exactly how I get stuck \u2014 but cap them at three and put them last.\n  4. If FOCUS.md is missing, say so in one line and treat everything as ADJACENT.\n", "schedule": {"kind": "cron", "cron": "30 5 * * 0", "fire_at": null, "timezone": "local"}, "workspace": "/home/iconbaypark2900/OpenWorker/__task__task-c708f5430e", "origin_surface": "cowork", "origin_session_id": "", "agent": "repo-ops", "id": "task-c708f5430e", "task_session_id": "__task__task-c708f5430e", "model": null, "notify_on_completion": true, "notify_target": null, "always_allowed_tools": ["brain_note", "brain_recall", "grep", "list_files", "read_file", "read_file_lines", "remember", "run_shell", "todo_write", "web_fetch", "web_search", "write_file"], "always_allowed_commands": [], "enabled": true, "created_at": 1786987187.2849755, "updated_at": 1788103273.088933, "next_run": 1788687000.0, "last_run": 1788103270.0705755, "last_status": "incomplete", "run_count": 4, "max_runs": null, "seen_runs_at": 0.0}');
INSERT INTO scheduled_tasks VALUES('task-ecad448aa3',1,1788170400.0,'{"title": "Knowledge base \u2014 ingest yesterday''s findings", "instructions": "Take what the other automations wrote in the last 24 hours and put the findings into\nthe Qdrant knowledge base, so later jobs (and I) can retrieve them by meaning instead of by\nremembering which file they were in.\n\nFIND the new outputs:\n  `find /home/iconbaypark2900 -maxdepth 3 -path ''*__task__*'' -name ''*.md'' -mtime -1 | head -25`\n  (task workspaces live under both ~/OpenWorker and ~/openworker-tasks \u2014 never assume one base)\n  Skip FOCUS.md \u2014 it is a copy, not a finding.\n\nFOR EACH FILE:\n  1. read_file it.\n  2. Pull out the DISCRETE FINDINGS \u2014 a claim that would still be worth retrieving in three\n     months. A paper with its result, a breakage with its cause, a repo change with its\n     consequence, a grant with its deadline. Not section headings, not \"nothing new today\".\n  3. mcp__qdrant__qdrant-qdrant-find on the finding''s subject FIRST. If it is already stored, skip it \u2014\n     near-duplicates make every future retrieval worse. This check is not optional.\n  4. mcp__qdrant__qdrant-qdrant-store each new one:\n       information: one self-contained sentence. It must make sense with no surrounding\n                    context, because retrieval returns it alone. Include the identifier\n                    (arXiv id, repo name, package version, URL) inside the sentence.\n       metadata:    {\"job\": \"<automation title>\", \"date\": \"<YYYY-MM-DD>\",\n                     \"cadence\": \"daily\", \"focus\": \"on|adjacent\", \"kind\":\n                     \"paper|breakage|repo|grant|job|news|analysis\",\n                     \"source\": \"<absolute path of the file it came from>\"}\n     The \"focus\" value comes from the ON-FOCUS / ADJACENT tag the source file carries. If the\n     file has no tag, use \"adjacent\".\n\nLEDGER: write /home/iconbaypark2900/OpenWorker/knowledge/ingest/<YYYY-MM-DD>.md \u2014 a table of file, findings stored, findings\nskipped as duplicates. Create the directory first if it does not exist. Then report the running\ntotal: `curl -s http://127.0.0.1:6333/collections/default | head -c 300`.\n\nBUDGET: at most 25 stores and 25 finds per run. If a day produces more than that, store the\nON-FOCUS ones first and say in the ledger what you left behind.\n\nRULES:\n  - Store only what you read in a file today. Never store from memory, and never store a\n    finding you inferred rather than read \u2014 the KB is retrieved as fact later.\n  - A file that says \"nothing new\" produces zero points. That is a correct outcome, not a\n    failed run.\n  - The markdown files stay the source of truth. Qdrant holds the retrievable claim and a\n    path back to the file; it is an index, not a replacement.\n\nSHELL RULES \u2014 you are unattended, so keep every command small and reviewable:\n  - NEVER inline a multi-line script (no heredocs). Write it to a file with write_file, then\n    run that file.\n  - One command does one thing. Cap output: head, tail -n, wc -l, --quiet.\n  - Use native paths (/home/iconbaypark2900/...). The filesystem MCP server sees this machine''s\n    home as /data/home instead, so its paths and shell paths are NOT interchangeable \u2014 prefer\n    shell for files, and only use qdrant through MCP.\n  - /home/iconbaypark2900/OpenWorker/knowledge is a WRITABLE ROOT of this session. Use the normal file\n    tools on it with absolute paths \u2014 read_file, write_file, list_files all work there, and\n    they are more reliable than shell redirection. Shell is for git, sqlite, find and curl.\n\nCONTINUITY \u2014 do this FIRST, before any searching:\n  1. list_files in your workspace and read the 1-2 most recent prior outputs of this\n     same job (they share this file-naming pattern).\n  2. Carry forward what is still live, mark what has closed or been resolved, and spend\n     your search budget on what is genuinely NEW since then.\n  3. If something you reported before has changed state, say so explicitly \u2014 \"X, first\n     flagged <date>, is now <state>\" is worth more than rediscovering X as if it were new.\n  4. Never re-report an unchanged item as a fresh finding.\nThis job runs on a schedule and its outputs accumulate; the value is in the running\nrecord, not in a fresh cold start every time.\n\nFOCUS \u2014 do this before anything else:\n  1. read_file FOCUS.md in your own workspace. It is rewritten every Monday from what I\n     actually worked on: the projects in play, the open questions, and what I have parked.\n  2. Tag every item you report ON-FOCUS or ADJACENT. ON-FOCUS bears on a project or open\n     question named in FOCUS.md; ADJACENT does not, but is worth knowing anyway.\n  3. Lead with ON-FOCUS. Keep the ADJACENT ones \u2014 being shown only what I already care about\n     is exactly how I get stuck \u2014 but cap them at three and put them last.\n  4. If FOCUS.md is missing, say so in one line and treat everything as ADJACENT.\n\nTHREADS \u2014 keep the durable record current, not just the dated one:\n  Your dated report is the evidence; the brain''s threads are the memory a future session reads.\n  After writing the report, for each subject that MOVED this run:\n    1. `brain_recall` the subject to find its existing thread \u2014 extend that thread, never fork a\n       near-duplicate of it.\n    2. `brain_note` one entry: what changed, with the specifics, and `source` set to the file you\n       just wrote.\n    3. Pass `now` ONLY if the subject''s current state actually changed. That line is what keeps a\n       stale claim from being retrieved later as if it were still true.\n  A quiet run notes nothing. Inventing movement to have something to record is worse than silence.\n", "schedule": {"kind": "cron", "cron": "0 6 * * *", "fire_at": null, "timezone": "local"}, "workspace": "/home/iconbaypark2900/openworker-tasks/__task__task-ecad448aa3", "origin_surface": "cowork", "origin_session_id": "", "agent": "repo-ops", "id": "task-ecad448aa3", "task_session_id": "__task__task-ecad448aa3", "model": null, "notify_on_completion": true, "notify_target": null, "always_allowed_tools": ["brain_note", "brain_recall", "grep", "list_files", "mcp__qdrant__qdrant-qdrant-find", "mcp__qdrant__qdrant-qdrant-store", "read_file", "read_file_lines", "remember", "run_shell", "todo_write", "write_file"], "always_allowed_commands": [], "enabled": true, "created_at": 1787415295.9085045, "updated_at": 1788103273.174355, "next_run": 1788170400.0, "last_run": 1788103270.0707324, "last_status": "incomplete", "run_count": 7, "max_runs": null, "seen_runs_at": 1787834241.7817972}');
INSERT INTO task_runs VALUES('run-fdda11eeba','task-c685e22a0b',1786891901.302114,'{"task_id": "task-c685e22a0b", "run_id": "run-fdda11eeba", "started_at": 1786891901.302114, "finished_at": 1786892030.4916718, "status": "ok", "result_text": "Your morning briefing is ready \u2014 a 5-bullet digest of the last 24\u201336 hours:\n\n1. **Indonesia** \u2014 M7.7 quake off Flores killed 53+, injured 130+, with tsunamis and hampered relief\n2. **Red Sea** \u2014 Yemen suspended port operations after fresh Houthi ship attacks amid the US\u2013Iran conflict\n3. **Google** \u2014 launched Gemini 3.7 Flash, a cheaper, faster agentic/coding workhorse\n4. **Apple** \u2014 trained its own Chinese-market AI model with Alibaba, cleared by regulators\n5. **AI market** \u2014 OpenAI/Anthropic price cuts amid a ~$1.5T Big Tech AI capex buildout\n\n[Morning News Briefing 2026-08-16](artifact:morning-news-briefing-2026-08-16.md)", "artifacts": ["morning-news-briefing-2026-08-16.md"], "error": null, "trigger": "manual", "session_id": "__run__run-fdda11eeba"}');
