INSERT INTO task_runs VALUES('run-bdd42dd540','task-092a6d85f2',1786908785.53168439,'{"task_id": "task-092a6d85f2", "run_id": "run-bdd42dd540", "started_at": 1786908785.5316844, "finished_at": 1786909866.5019655, "status": "ok", "result_text": "Done \u2014 the digest is written. Here''s the short version:\n\n**[Grant + Funding Digest, Week 33 2026](grants-2026-week-33.md)**\n\n- **Nothing urgent (\u226414 days) actually qualifies** \u2014 the two items in that window (NASA CCRPP, Space Force SSTI) both require an existing SBIR award or a university. They''re flagged so next week''s run skips them.\n- **Best real fits for your profile** (independent, no PhD, no company, US-based):\n  - **[FELLOWSHIP] Cleveland Clinic\u2013Denmark Quantum\u2013AI Biomedical Frontiers** (Novo Nordisk Fonden, up to ~$250K, reopens Sept 2026) \u2014 the only program this cycle where a solo individual can win for your exact QML-biomedical project.\n  - **[RESEARCH] NSF ACCESS Explore allocations** \u2014 free supercomputing, rolling, one-page abstract; easiest win on the list, apply now.\n  - **[SBIR] NIH omnibus (Sept 5, 2026), DOD Open Topics/SBIR 26.2, DOE Genesis Mission (Sept 10), NSF SBIR (Nov 4, 2026)** \u2014 all strong topical matches (QML-biomedicine, post-quantum RNG, quantum software), but every one **requires a registered US small business** \u2014 the honest structural gap in the plan, spelled out in the digest.\n- **Watch items:** NSF X-Labs ($1.5M\u2013$50M/yr for independent R&D teams \u2014 the closest structural fit to you personally, both 2026 topics closed but more expected), DOE ERCAP window closing ~October, and NSF AI Hubs (Nov 4, no solo entry).\n- **Excluded with reasons:** IBM Quantum Credits (academic-staff only), AWS/Google/Azure research credits (faculty only), FutureHouse (PhD/postdoc only), OpenAI/Anthropic safety fellowships (mostly salaried-employer programs the digest excludes anyway).\n\nRecommended order over the next 60 days is in the file: ACCESS pitch + SAM.gov registration this week, company decision before Sept 5, ERCAP request by end of October.", "artifacts": ["grants-2026-week-33.md"], "error": null, "trigger": "schedule", "session_id": "__run__run-bdd42dd540"}');
INSERT INTO task_runs VALUES('run-68d7b6e315','task-1b2c4d3f13',1786964417.34232258,'{"task_id": "task-1b2c4d3f13", "run_id": "run-68d7b6e315", "started_at": 1786964417.3423226, "finished_at": 1786965074.9449537, "status": "ok", "result_text": "I''ve found some strong candidates already, including an RSI paper called HELIX. Now I''ll check the remaining quant-ph entries and scan cs.LG to make sure I''m not missing any architecture or quantum ML papers.", "artifacts": [], "error": null, "trigger": "schedule", "session_id": "__run__run-68d7b6e315"}');
INSERT INTO task_runs VALUES('run-fc9b670d42','task-c685e22a0b',1786968017.39641451,'{"task_id": "task-c685e22a0b", "run_id": "run-fc9b670d42", "started_at": 1786968017.3964145, "finished_at": 1786968207.1304011, "status": "ok", "result_text": "Done \u2014 your morning briefing is ready. Five bullets covering the biggest tech and world stories from the last 24 hours:\n\n1. **Stripe buys OpenRouter for $7B+** (AI billing/routing rail)\n2. **AI spending reality check** \u2014 ~$3T in off-balance-sheet AI commitments + $12B PJM auction error, chip stocks in a 4-week sell-off\n3. **Earthquake disasters** \u2014 M7.7 Indonesia (38\u201351+ dead), Colombia toll now 294\n4. **War & diplomacy** \u2014 new Ukraine strikes, Trump cuts US\u2013South Korea exercises, Gaza mediation\n5. **CISA KEV alert** \u2014 Windows afd.sys (CVE-2026-68820) actively exploited, patch by Aug 25\n\nNote: these are compiled from aggregator roundups and headline snippets, not primary sources \u2014 worth a light verification pass before you act on any of them.\n\n[Morning Briefing \u2014 2026-08-17](briefing-2026-08-17.md)", "artifacts": ["briefing-2026-08-17.md"], "error": null, "trigger": "schedule", "session_id": "__run__run-fc9b670d42"}');
INSERT INTO task_runs VALUES('run-2cda04ecaf','task-c6cf366b90',1786971617.4548316,'{"task_id": "task-c6cf366b90", "run_id": "run-2cda04ecaf", "started_at": 1786971617.4548316, "finished_at": 1786972840.0560613, "status": "ok", "result_text": "Done \u2014 shortlist written, 5 ranked matches, 6 draft files.\n\n\u26a0\ufe0f **Time-critical:** the **AIAF Fellowship** ($12K/8 wks, paid AI-alignment research, fully remote) closes **today, Aug 17 AoE** \u2014 ranked #1, drafts ready to support an immediate application.\n\nTop 3 with full drafts in `drafts/`:\n1. **AIAF Fellowship 2026** (fellowship) \u2014 deadline today; fit ~7/10\n2. **Databricks AI Engineer \u2013 FDE** ($153\u2013210K, US remote) \u2014 RAG/agents/DSPy/LangChain hit almost exactly the posted JD; gap: ~2 yrs vs. 4+\n3. **Vytalize Health AI Engineer** (US remote, healthcare agents) \u2014 best domain match: your insurance/claims RAG + SLM-agent ETL work is essentially their JD\n\nAlso listed: Oowlish Senior LLM Engineer (posted Aug 5, $90\u2013140K) and MLH Fellowship (deadline Aug 31). Checked-and-rejected section covers closed residency cycles and funding-only fellowships per scope. One honest caveat, noted in the file: today''s genuinely last-24h postings were thin, so two standard roles are \"active as of today (verified live)\" rather than posted yesterday \u2014 that''s flagged per row.\n\n[Shortlist \u2014 jobs-2026-08-17.md](jobs-2026-08-17.md)", "artifacts": ["jobs-2026-08-17.md", "drafts/cover-letter-vytalize.md", "drafts/resume-tweaks-vytalize.md", "drafts/cover-letter-databricks.md", "drafts/resume-tweaks-databricks.md", "drafts/cover-letter-aiaf.md", "drafts/resume-tweaks-aiaf.md"], "error": null, "trigger": "schedule", "session_id": "__run__run-2cda04ecaf"}');
INSERT INTO task_runs VALUES('run-092bd4bcd0','task-092a6d85f2',1786975217.50484371,'{"task_id": "task-092a6d85f2", "run_id": "run-092bd4bcd0", "started_at": 1786975217.5048437, "finished_at": 1786976401.6039104, "status": "ok", "result_text": "Digest complete \u2014 [grants-2026-week-33.md](grants-2026-week-33.md).\n\nKey findings, straight version:\n\n- **2 urgent (days):** DARPA SBIR **FALCON** (ML+LLM topic, ~$200K) closes **Aug 19 \u2014 2 days away**, but requires a registered US small business; Lightcone Commons AI-grants round closes **Aug 23**, though the GCR framing is a stretch for your work.\n- **Best genuine fit, no company needed:** IBM Quantum Credits (rolling) \u2014 your hybrid QML pipeline already targets IBM QPU backends.\n- **Rolling open now:** Leo Gao''s $10K microgrants, BlueDot Rapid Grants, AIAF, TAIF ($10K\u2013$150K), Halcyon (up to $1M) \u2014 all built for independent researchers without an institution.\n- **Future fixed deadlines:** NSF SBIR/STTR Phase I closes **Nov 4, 2026** (deep-tech quantum/ML is a strong topical fit), NIH SBIR Jan 5, 2027 (only qualifies if you partner with an institution).\n- **Honest structural gap:** no registered entity in the profile, which gates every SBIR/STARTUP item including the six/seven-figure ones. The Anthropic and OpenAI fellowships were deliberately skipped as org employment per this digest''s scope; I noted that in the dropped section.\n\nThe digest is sorted by deadline, with closed items dropped and each entry carrying a frank \"do you actually qualify\" line.", "artifacts": ["grants-2026-week-33.md"], "error": null, "trigger": "schedule", "session_id": "__run__run-092bd4bcd0"}');
