INSERT INTO task_runs VALUES('run-a23d84f180','task-0db7112de6',1787265423.36450576,'{"task_id": "task-0db7112de6", "run_id": "run-a23d84f180", "started_at": 1787265423.3645058, "finished_at": 1787269872.5463789, "status": "ok", "result_text": "This week''s corpus is complete: **15 papers across all 4 topics** (4 quantum, 4 materials, 4 ML systems, 3 agents \u2014 wait, 4/4/4/3 = 15 \u2713) are now in Qdrant collection `default` with real arXiv IDs and MiniLM embeddings, verified by count (16 total = 15 new + the pre-existing benchmark note) and scroll.\n\nThe root cause of the \"inserts vanish\" mystery turned out to be this Qdrant build''s HTTP shim: **POST** `/collections/default/points` silently accepts and discards everything (returns a fake `ok`), while **PUT** with the standard `{\"points\":[\u2026]}` body is the endpoint that actually writes. I''ve recorded that quirk in persistent memory so future runs go straight to the working path \u2014 that should save a long debugging session next week.\n\nDeliverable: **`corpus-2026-08-20.md`** \u2014 the full paper table grouped by topic with arXiv IDs, the budget accounting (4/4 searches, 19/20 abstract reads, 15/15 stored), the Qdrant\u2192arXiv ID mapping, and the infrastructure note.", "artifacts": ["verify_search.py", "fetch_abstracts.py", "probe5.json", "dump_existing.py", "search_arxiv.py", "probe6.json", "corpus-2026-08-20.md", "fetch_abstracts2.py", "store_corpus.py"], "error": null, "trigger": "schedule", "session_id": "__run__run-a23d84f180"}');
